def test_format_timestamp() -> None:
    assert format_timestamp(TS) == "2026-11-18T12:30:15.123456Z"
    naive = TS.replace(tzinfo=None)
    assert format_timestamp(naive) == "2026-11-18T12:30:15.123456Z"
    offset = TS.astimezone(timezone(timedelta(hours=2)))
    assert format_timestamp(offset) == "2026-11-18T12:30:15.123456Z"


