def test_record_defaults() -> None:
    record = LogRecord("hello")
    assert record.severity is Severity.INFO
    assert record.severity_text == "INFO"
    assert record.timestamp.tzinfo is not None
    assert dict(record.attributes) == {}
    assert LogRecord("x", severity=Severity.WARN).severity_text == "WARN"
    assert LogRecord("x", severity_text="warning").severity_text == "warning"


def test_record_json_round_trip() -> None:
    record = LogRecord(
        "hello",
        severity=Severity.ERROR,
        timestamp=TS,
        attributes={"n": 1, "nested": {"a": [1, "b"]}, "t": ("x",)},
        resource={"service.name": "svc"},
        trace_id="4bf92f3577b34da6a3ce929d0e0e4736",
        span_id="00f067aa0ba902b7",
        trace_flags=1,
        observed_timestamp=TS,
    )
    data = record.to_json()
    assert data == {
        "timestamp": "2026-11-18T12:30:15.123456Z",
        "observedTimestamp": "2026-11-18T12:30:15.123456Z",
        "severity": 17,
        "severityText": "ERROR",
        "body": "hello",
        "attributes": {"n": 1, "nested": {"a": [1, "b"]}, "t": ["x"]},
        "resource": {"service.name": "svc"},
        "traceId": "4bf92f3577b34da6a3ce929d0e0e4736",
        "spanId": "00f067aa0ba902b7",
        "traceFlags": 1,
    }
    back = LogRecord.from_json(data)
    assert back.to_json() == data
    assert record.json_size() == len(record.to_json_str().encode())


def test_record_json_without_trace() -> None:
    data = LogRecord("x", timestamp=TS, span_id="00f067aa0ba902b7").to_json()
    assert "traceId" not in data
    assert data["spanId"] == "00f067aa0ba902b7"
    assert "observedTimestamp" not in data
    only_trace = LogRecord("x", timestamp=TS, trace_id="ab" * 16).to_json()
    assert "spanId" not in only_trace
    assert "traceFlags" not in only_trace


def test_record_from_json_variants() -> None:
    record = LogRecord.from_json(
        {"timestamp": "2026-11-18T12:30:15Z", "body": {"k": "v"}, "severityText": "warning"}
    )
    assert record.body == '{"k":"v"}'
    assert record.severity is Severity.WARN
    assert record.trace_flags is None
    plain = LogRecord.from_json({"timestamp": "2026-11-18T12:30:15Z", "body": "b"})
    assert plain.severity is Severity.INFO
    assert plain.severity_text == "INFO"
    assert plain.observed_timestamp is None
    numbered = LogRecord.from_json(
        {"timestamp": "2026-11-18T12:30:15.123456789Z", "body": "b", "severity": 13}
    )
    assert numbered.severity is Severity.WARN
    assert numbered.timestamp == TS.replace(microsecond=123456, second=15)


def test_record_from_json_missing_field() -> None:
    with pytest.raises(ValidationError, match="body"):
        LogRecord.from_json({"timestamp": "2026-11-18T12:30:15Z"})


def test_unicode_size_counts_bytes() -> None:
    small = LogRecord("a", timestamp=TS).json_size()
    assert LogRecord("é", timestamp=TS).json_size() == small + 1


